CREATE TYPE "Role" AS ENUM ('ADMINISTRADORA','PORTERO','RESIDENTE');
CREATE TYPE "PackageStatus" AS ENUM ('RECIBIDO','ENTREGADO');
CREATE TYPE "ReservationStatus" AS ENUM ('PENDIENTE','APROBADA','RECHAZADA','CANCELADA');
CREATE TYPE "PQRSKind" AS ENUM ('PETICION','QUEJA','RECLAMO','SUGERENCIA');
CREATE TYPE "PQRSStatus" AS ENUM ('RECIBIDA','EN_REVISION','RESPONDIDA','CERRADA');
CREATE TYPE "Priority" AS ENUM ('BAJA','MEDIA','ALTA','URGENTE');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"role" "Role" NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "User_email_key" ON "User"("email"); CREATE INDEX "User_role_active_idx" ON "User"("role","active");
CREATE TABLE "Tower" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE UNIQUE INDEX "Tower_name_key" ON "Tower"("name");
CREATE TABLE "Apartment" ("id" TEXT PRIMARY KEY,"number" TEXT NOT NULL,"towerId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Apartment_towerId_fkey" FOREIGN KEY("towerId") REFERENCES "Tower"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE UNIQUE INDEX "Apartment_towerId_number_key" ON "Apartment"("towerId","number"); CREATE INDEX "Apartment_number_idx" ON "Apartment"("number");
CREATE TABLE "ResidentProfile" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"apartmentId" TEXT NOT NULL,"phone" TEXT,"consentAt" TIMESTAMP(3),CONSTRAINT "ResidentProfile_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "ResidentProfile_apartmentId_fkey" FOREIGN KEY("apartmentId") REFERENCES "Apartment"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE UNIQUE INDEX "ResidentProfile_userId_key" ON "ResidentProfile"("userId"); CREATE INDEX "ResidentProfile_apartmentId_idx" ON "ResidentProfile"("apartmentId");
CREATE TABLE "Package" ("id" TEXT PRIMARY KEY,"apartmentId" TEXT NOT NULL,"recipientName" TEXT NOT NULL,"carrier" TEXT NOT NULL,"trackingNumber" TEXT,"description" TEXT,"observations" TEXT,"status" "PackageStatus" NOT NULL DEFAULT 'RECIBIDO',"receivedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"recordedById" TEXT NOT NULL,CONSTRAINT "Package_apartmentId_fkey" FOREIGN KEY("apartmentId") REFERENCES "Apartment"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "Package_recordedById_fkey" FOREIGN KEY("recordedById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE INDEX "Package_apartmentId_status_receivedAt_idx" ON "Package"("apartmentId","status","receivedAt"); CREATE INDEX "Package_receivedAt_status_idx" ON "Package"("receivedAt","status");
CREATE TABLE "PackageDelivery" ("id" TEXT PRIMARY KEY,"packageId" TEXT NOT NULL,"receiverName" TEXT NOT NULL,"receiverType" TEXT NOT NULL,"observations" TEXT,"deliveredAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"deliveredById" TEXT NOT NULL,CONSTRAINT "PackageDelivery_packageId_fkey" FOREIGN KEY("packageId") REFERENCES "Package"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "PackageDelivery_deliveredById_fkey" FOREIGN KEY("deliveredById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE UNIQUE INDEX "PackageDelivery_packageId_key" ON "PackageDelivery"("packageId");
CREATE TABLE "AuthorizedPerson" ("id" TEXT PRIMARY KEY,"residentProfileId" TEXT NOT NULL,"name" TEXT NOT NULL,"documentLast4" TEXT,"active" BOOLEAN NOT NULL DEFAULT true,CONSTRAINT "AuthorizedPerson_residentProfileId_fkey" FOREIGN KEY("residentProfileId") REFERENCES "ResidentProfile"("id") ON DELETE CASCADE ON UPDATE CASCADE); CREATE INDEX "AuthorizedPerson_residentProfileId_active_idx" ON "AuthorizedPerson"("residentProfileId","active");
CREATE TABLE "CommonArea" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"capacity" INTEGER NOT NULL,"schedule" JSONB NOT NULL); CREATE UNIQUE INDEX "CommonArea_name_key" ON "CommonArea"("name");
CREATE TABLE "Reservation" ("id" TEXT PRIMARY KEY,"commonAreaId" TEXT NOT NULL,"apartmentId" TEXT NOT NULL,"userId" TEXT NOT NULL,"date" DATE NOT NULL,"slot" TEXT NOT NULL,"attendees" INTEGER NOT NULL,"status" "ReservationStatus" NOT NULL DEFAULT 'PENDIENTE',"rejectionReason" TEXT,"approvedById" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Reservation_commonAreaId_fkey" FOREIGN KEY("commonAreaId") REFERENCES "CommonArea"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "Reservation_apartmentId_fkey" FOREIGN KEY("apartmentId") REFERENCES "Apartment"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "Reservation_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "Reservation_approvedById_fkey" FOREIGN KEY("approvedById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE INDEX "Reservation_commonAreaId_date_slot_status_idx" ON "Reservation"("commonAreaId","date","slot","status"); CREATE INDEX "Reservation_apartmentId_date_idx" ON "Reservation"("apartmentId","date");
CREATE UNIQUE INDEX "Reservation_one_approved_slot" ON "Reservation"("commonAreaId","date","slot") WHERE "status" = 'APROBADA';
CREATE TABLE "PQRS" ("id" TEXT PRIMARY KEY,"ticket" TEXT NOT NULL,"userId" TEXT NOT NULL,"kind" "PQRSKind" NOT NULL,"subject" TEXT NOT NULL,"description" TEXT NOT NULL,"status" "PQRSStatus" NOT NULL DEFAULT 'RECIBIDA',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "PQRS_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE UNIQUE INDEX "PQRS_ticket_key" ON "PQRS"("ticket"); CREATE INDEX "PQRS_userId_createdAt_idx" ON "PQRS"("userId","createdAt"); CREATE INDEX "PQRS_status_createdAt_idx" ON "PQRS"("status","createdAt");
CREATE TABLE "PQRSHistory" ("id" TEXT PRIMARY KEY,"pqrsId" TEXT NOT NULL,"userId" TEXT NOT NULL,"status" "PQRSStatus" NOT NULL,"message" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PQRSHistory_pqrsId_fkey" FOREIGN KEY("pqrsId") REFERENCES "PQRS"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "PQRSHistory_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE); CREATE INDEX "PQRSHistory_pqrsId_createdAt_idx" ON "PQRSHistory"("pqrsId","createdAt");
CREATE TABLE "AuditLog" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"action" TEXT NOT NULL,"entity" TEXT NOT NULL,"entityId" TEXT NOT NULL,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AuditLog_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE); CREATE INDEX "AuditLog_entity_entityId_createdAt_idx" ON "AuditLog"("entity","entityId","createdAt"); CREATE INDEX "AuditLog_userId_createdAt_idx" ON "AuditLog"("userId","createdAt");
CREATE TABLE "ShiftNovelty" ("id" TEXT PRIMARY KEY,"authorId" TEXT NOT NULL,"category" TEXT NOT NULL,"description" TEXT NOT NULL,"shift" TEXT NOT NULL,"priority" "Priority" NOT NULL DEFAULT 'MEDIA',"followUp" BOOLEAN NOT NULL DEFAULT false,"followedAt" TIMESTAMP(3),"followedById" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ShiftNovelty_authorId_fkey" FOREIGN KEY("authorId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE); CREATE INDEX "ShiftNovelty_createdAt_shift_idx" ON "ShiftNovelty"("createdAt","shift"); CREATE INDEX "ShiftNovelty_followUp_priority_idx" ON "ShiftNovelty"("followUp","priority");
